#pragma once
#include "native_walker_codec.hpp"
namespace game_lab {
// Normal newcomer family generated by originalBuildingImmigrant. A separate
// magic/schema never changes Well or type13 migrant bytes. Graph/target/route
// and aggregate population proofs remain runtime bridge responsibilities.
// A separate type11 policy and magic reuse the exact same 118 named members.
// Home/link, pool, route and graph references remain bridge responsibilities.
inline constexpr unsigned nativeImmigrantCodecVersion=1;
inline constexpr const char* nativeImmigrantCodecMagic="NATIVE-IMMIGRANT";
inline constexpr size_t nativeImmigrantCodecFieldCount=118;
inline constexpr size_t nativeImmigrantCodecMaxBytes=16384;
namespace native_walker_detail {
inline std::string validateImmigrant(const OriginalFigure& f){
    if(f.type!=11)return "not_immigrant_type11";
    if(f.alive!=1)return "not_live_immigrant";
    if(f.runtimeClass!=OriginalFigureClass::Figure)return "runtime_class_not_figure";
    if(f.action<6||f.action>8)return "unsupported_immigrant_action";
    if(f.owner!=0)return "immigrant_owner_not_zero";
    if(!f.slot||f.slot>=2000)return "immigrant_slot_out_of_range";
    if(f.home<=0||f.home>=4000)return "immigrant_home_out_of_range";
    if(!f.employmentAmount)return "immigrant_people_required";
    return {};
}
}
inline std::optional<std::string> encodeNativeImmigrant(const OriginalFigure& figure,std::string& error){
    using namespace native_walker_detail;
    error=validateImmigrant(figure);if(!error.empty())return std::nullopt;
    if(fieldCount()!=nativeImmigrantCodecFieldCount){error="field_schema_changed";return std::nullopt;}
    Writer w;w.out=std::string(nativeImmigrantCodecMagic)+' '+std::to_string(nativeImmigrantCodecVersion)+' '+std::to_string(nativeImmigrantCodecFieldCount)+'\n';
    auto copy=figure;visitWellWalker(w,copy);
    if(w.out.size()>nativeImmigrantCodecMaxBytes){error="encoded_size_limit";return std::nullopt;}
    return w.out;
}
inline std::optional<OriginalFigure> decodeNativeImmigrant(const std::string& bytes,std::string& error){
    using namespace native_walker_detail;error.clear();
    if(bytes.size()>nativeImmigrantCodecMaxBytes){error="input_size_limit";return std::nullopt;}
    if(bytes.empty()||bytes.back()!='\n'){error="missing_final_newline";return std::nullopt;}
    if(bytes.find('\0')!=std::string::npos||bytes.find('\r')!=std::string::npos){error="invalid_character";return std::nullopt;}
    if(fieldCount()!=nativeImmigrantCodecFieldCount){error="field_schema_changed";return std::nullopt;}
    std::vector<std::string_view> rows;const std::string_view all(bytes);size_t start=0;
    while(start<all.size()){const size_t end=all.find('\n',start);rows.push_back(all.substr(start,end-start));start=end+1;}
    const std::string expected=std::string(nativeImmigrantCodecMagic)+' '+std::to_string(nativeImmigrantCodecVersion)+' '+std::to_string(nativeImmigrantCodecFieldCount);
    if(rows.empty()||rows.front()!=expected){error=rows.empty()||rows.front().rfind(std::string(nativeImmigrantCodecMagic)+' ',0)!=0?"bad_magic":"unsupported_version_or_field_count";return std::nullopt;}
    Reader r;
    for(size_t n=1;n<rows.size();++n){const auto row=rows[n];const size_t space=row.find(' ');
        if(space==std::string_view::npos||space==0||row.find(' ',space+1)!=std::string_view::npos){error="malformed_line";return std::nullopt;}
        r.lines.emplace_back(row.substr(0,space),row.substr(space+1));}
    if(r.lines.size()!=nativeImmigrantCodecFieldCount){error=r.lines.size()<nativeImmigrantCodecFieldCount?"missing_fields":"trailing_data";return std::nullopt;}
    OriginalFigure f;visitWellWalker(r,f);
    if(!r.error.empty()){error=r.error;return std::nullopt;}
    if(r.at!=r.lines.size()){error="trailing_data";return std::nullopt;}
    error=validateImmigrant(f);if(!error.empty())return std::nullopt;
    return f;
}
} // namespace game_lab
